from expand_a_common import *
d='p2-t1-d01'
item(d,6,'Khi người dùng kỳ vọng công cụ AI làm công việc thay họ, thay đổi sản phẩm nào phù hợp nhất?', ['Thiết kế quanh kết quả công việc và ngữ cảnh cá nhân','Giữ nguyên quy trình thao tác thủ công và chỉ thêm ô chat','Định nghĩa giá trị chủ yếu bằng số tính năng người dùng phải tự cấu hình'],'a','Kỳ vọng dịch chuyển sang công việc được hoàn thành, cá nhân hóa và phản hồi nhanh.')
item(d,7,'Mô hình trả phí theo output thay vì theo seat gắn giá sản phẩm với điều gì?', ['Kết quả công việc được tạo ra','Số tài khoản được cấp dù chưa thực hiện công việc','Số bước người dùng phải tự thao tác'],'a','Output pricing gắn đơn vị thu phí với phần việc được giao và hoàn thành.')
item(d,16,'Một tính năng nằm ngay trong hướng mở rộng chiến lược của nhà cung cấp model lớn tạo rủi ro nào cho startup?', ['Năng lực đó có thể được tích hợp vào nền tảng, làm giảm khác biệt của sản phẩm','Có model mạnh hơn sẽ tự động tăng switching cost của startup','Chỉ cần đổi prompt là đủ bảo vệ khác biệt lâu dài'],'a','Khi nền tảng hấp thụ chức năng, sản phẩm cần lý do tồn tại vượt việc cung cấp lại chức năng đó.')
item(d,17,'Một thin wrapper chỉ bổ sung ít điều khiển quanh model dễ mất lợi thế trong tình huống nào?', ['Model gốc tích hợp chính năng lực mà wrapper đang bổ sung','Khách hàng cần workflow và trách nhiệm vận hành chuyên biệt hơn','Sản phẩm tích lũy được quy trình đánh giá theo domain riêng'],'a','Khác biệt chỉ dựa trên thiếu sót tạm thời của model dễ bị thu hẹp khi model cải tiến.')
item(d,20,'Vertical AI cần kết hợp hai năng lực nào?', ['Năng lực AI và chuyên môn domain','Năng lực AI và tăng số model mà không cần hiểu quy trình','Chuyên môn domain và bỏ qua khả năng/thất bại của AI'],'a','AI expert và domain expert cùng tạo hệ thống vừa hoạt động kỹ thuật vừa phù hợp công việc.')
item(d,22,'Hệ thống chạy đúng kỹ thuật nhưng kết quả sai nghiệp vụ; chuyên gia nghiệp vụ lại khó giải thích lỗi cho kỹ sư. Vấn đề cốt lõi là gì?', ['Khoảng cách giữa năng lực xây AI và khả năng biểu đạt phán đoán domain','Chỉ thiếu thêm một model có context window dài hơn','Chỉ thiếu thêm giao diện để nhập nhiều yêu cầu hơn'],'a','Chuyên môn cần được chuyển thành tiêu chí và phản hồi mà hệ thống có thể sử dụng.')
item(d,23,'Những hoạt động nào giúp thu hẹp khoảng cách AI–domain? (Chọn tất cả đáp án đúng.)',['AI expert học domain và khai thác insight từ chuyên gia','Domain expert học khả năng và failure modes của AI','Giữ tiêu chí nghiệp vụ dưới dạng trực giác không giải thích được','Để hai nhóm chỉ trao đổi sau khi hệ thống hoàn tất'],['a','b'],'Học hai chiều giúp biến phán đoán domain thành yêu cầu, tiêu chí và cơ chế sửa lỗi.')
item(d,24,'Lợi thế của một sản phẩm AI chuyên ngành nên được tìm ở đâu ngoài bản thân model?', ['Workflow và cách đưa phán đoán chuyên gia vào hệ thống','Chỉ tên model hiện đang đứng đầu benchmark','Chỉ số lượng model có thể chọn trong dropdown'],'a','Giá trị đến từ cách AI thực hiện công việc cụ thể và tích hợp hiểu biết chuyên ngành.')
item(d,25,'Một chuyên gia trực tiếp đọc output, sửa prompt và bổ sung nguồn domain đang đảm nhận vai trò nào?', ['Oracle','Evaluator chuyên xây tiêu chí và quản lý nhiều raters','Architect thiết kế vòng học tự cải thiện quy mô lớn'],'a','Oracle dùng phán đoán chuyên môn trực tiếp để đánh giá và cải thiện output.')
item(d,25,'Khi một chuyên gia không thể tự kiểm tra mọi output, vai trò Evaluator cần làm gì?', ['Chuyển trực giác về chất lượng thành tiêu chí đo và tổ chức đánh giá ở quy mô lớn','Tiếp tục tự sửa từng output mà không định nghĩa tiêu chí','Thay mọi đánh giá bằng việc model có sinh đủ số token hay không'],'a','Evaluator định nghĩa thế nào là tốt và tạo cách đo, phối hợp raters để mở rộng đánh giá.')
item(d,25,'Vai trò Architect phù hợp với mục tiêu nào?', ['Thiết kế hệ thống học và cải thiện từ tương tác mà không cần chuyên gia chạm từng vòng','Giữ chuyên gia làm người sửa thủ công mọi response','Chỉ viết thêm prompt riêng cho từng trường hợp mới'],'a','Architect thiết kế cơ chế cải thiện ở cấp hệ thống khi biến số thị trường quá lớn cho xử lý từng ca.')
item(d,30,'Trước khi chọn AI làm giải pháp, một AI Product Manager cần trả lời câu hỏi nào?', ['AI có thực sự giải quyết bài toán này tốt hơn và tạo giá trị sử dụng không?','Có model mới nào để đưa vào roadmap cho đủ xu hướng không?','Có thể dựng demo nhanh đến đâu trước khi xác định vấn đề?'],'a','Judgment gate nối khả năng AI với tính hữu dụng và tác động kinh doanh.')
item(d,33,'Vì sao tư duy failure-first đặc biệt cần cho AI Product Manager?', ['Output không hoàn toàn tất định và hành vi có thể drift','Một bản demo đúng đã chứng minh mọi tình huống vận hành','Model mạnh làm loại bỏ nhu cầu định nghĩa failure modes'],'a','Sản phẩm cần dự kiến khi nào AI thất bại và cơ chế xử lý, thay vì chỉ chứng minh happy path.')
item(d,34,'Những thành phần nào cần bao quanh một AI core có tính không tất định? (Chọn tất cả đáp án đúng.)',['Evals và xử lý failure modes','Trust/safety và theo dõi drift','Quản lý cost','Chỉ kiểm tra response có được trả về hay không'],['a','b','c'],'AI core cần nhiều cơ chế kiểm soát chất lượng, an toàn, chi phí và thay đổi hành vi.')
item(d,37,'Khi AI làm prototype và iteration rẻ hơn, giá trị phán đoán của PM tập trung hơn vào đâu?', ['Chọn đúng vấn đề, đánh đổi và định nghĩa kết quả tốt','Tối đa số prototype mà không cần đo outcome','Đồng nhất khả năng dựng nhanh với nhu cầu thị trường đã được xác nhận'],'a','Chi phí tạo lựa chọn giảm không tự giải quyết việc lựa chọn hướng có giá trị.')
item(d,42,'Một bộ đếm số lượt giúp người chơi puzzle lập kế hoạch, nhưng không giúp người học khi họ không biết đáp án. Sai lầm thiết kế là gì?', ['Sao chép cơ chế mà chưa kiểm tra động lực hành vi có tương đương không','Đánh giá cơ chế dựa trên mục tiêu học thay vì chỉ nhìn mức phổ biến','Điều chỉnh pattern thành công theo đặc thù công việc mới'],'a','Scarcity có ích cho hoạch định nước đi nhưng không tạo kiến thức mà người học đang thiếu.')
item(d,43,'Thưởng gói premium cho người giới thiệu kém hấp dẫn khi nhóm dễ giới thiệu nhất đã có premium. Bài học là gì?', ['Kiểm tra giá trị phần thưởng đối với đúng nhóm thực hiện hành vi','Ưu đãi có hiệu quả ở sản phẩm khác sẽ có hiệu quả tương tự ở đây','Chọn phần thưởng theo giá niêm yết mà không xét quyền lợi hiện có'],'a','Pattern referral cần được kiểm tra với đối tượng, động lực và lợi ích thực tế của người nhận.')
d='p2-t1-d02'
item(d,3,'Trước khi phát triển lựa chọn giải pháp, product discovery cần làm rõ điều gì?', ['Giả thuyết vấn đề và bằng chứng về nhu cầu thực tế','Đặc tả hoàn chỉnh của giải pháp đầu tiên được đề xuất','Deadline triển khai trước khi tìm hiểu pain'],'a','Bằng chứng về vấn đề tạo cơ sở chọn giải pháp thay vì coi một directive là nhu cầu đã xác minh.')
item(d,4,'Yêu cầu “hãy làm push notification khi tài xế đến” còn thiếu thông tin quan trọng nào?', ['Vấn đề và hành vi nào cần thay đổi, ở ai và trong ngữ cảnh nào','Nội dung technical task để lập tức ước lượng sprint','Mẫu giao diện notification để chốt trước phỏng vấn'],'a','Một giải pháp được chỉ định có thể che nhiều pain khác nhau cần được khám phá.')
item(d,10,'Người nhận thông báo không nhất thiết là người chịu pain chính. Nên phân tích thêm những ai?', ['Người đổi hành vi, chịu hậu quả và hưởng lợi trong quy trình','Chỉ người trực tiếp bấm vào thông báo','Chỉ nhóm phát triển chịu trách nhiệm xây tính năng'],'a','Một luồng có thể liên quan hành khách, tài xế, nền tảng và support với hậu quả khác nhau.')
item(d,11,'Hành khách ở điểm đón đông xe cần tìm đúng xe nhanh. Job-to-be-done phù hợp nhất là gì?', ['Nhận ra và tìm được đúng xe để bắt đầu chuyến đi không phải chờ/gọi lại','Nhận nhiều thông báo hơn bất kể có tìm được xe hay không','Mở ứng dụng thường xuyên hơn trong thời gian chờ'],'a','Job nối trigger tại điểm đón với tiến bộ người dùng cần đạt, thay vì đồng nhất job với một feature.')
item(d,12,'Những giả thuyết nào có thể giải thích việc hành khách chưa lên xe? (Chọn tất cả đáp án đúng.)',['Chưa biết tài xế đã đến','Biết tài xế đến nhưng không tìm được đúng xe','Chưa sẵn sàng hoặc tài xế không liên lạc được','Mọi trường hợp đều do thiếu push notification'],['a','b','c'],'Cùng một hành vi quan sát có nhiều nguyên nhân, nên chưa thể suy ra một giải pháp duy nhất.')
item(d,13,'Hành khách đã biết tài xế đến nhưng không tìm được xe. Giải pháp nào trực tiếp phù hợp pain này hơn?', ['Hiển thị biển số/màu xe, vị trí chính xác hoặc hướng dẫn đi bộ','Lặp lại cùng thông báo “tài xế đã đến” thường xuyên hơn','Nhắc trước hai phút dù hành khách đã đứng đúng điểm đón'],'a','Cần hỗ trợ nhận diện và định vị xe, thay vì chỉ tăng tín hiệu đã đến.')
item(d,13,'Nếu hành khách thường chưa sẵn sàng khi xe đến, hướng thử nào phù hợp hơn việc cải thiện nhận diện biển số?', ['Nhắc trước hoặc hẹn thời điểm đến','Chỉ phóng to biển số khi xe đã đến','Chỉ thêm ảnh xe mà không tác động việc chuẩn bị'],'a','Pain về sẵn sàng đòi hỏi tác động thời điểm chuẩn bị, khác pain tìm đúng xe.')
item(d,15,'Câu hỏi phỏng vấn giới thiệu công cụ AI là “tuyệt vời” rồi hỏi người dùng có đồng ý dễ gây sai lệch gì?', ['Dẫn dắt người trả lời sang phản ứng với ý tưởng đã được đánh giá tích cực','Tự tạo bằng chứng về workflow hiện tại và mức độ pain','Giúp tách rõ hành vi đã xảy ra khỏi dự đoán tương lai'],'a','Lời giới thiệu tích cực và câu hỏi xác nhận dễ thu lời khen thay vì bằng chứng nhu cầu.')
item(d,17,'Câu hỏi nào thu được bằng chứng mạnh hơn cho vấn đề ra quyết định trong công việc?', ['“Lần gần nhất gặp quyết định khó, bạn đã làm gì và hậu quả ra sao?”','“Nếu công cụ chính xác hơn mọi công cụ hiện có, bạn sẽ dùng chứ?”','“Bạn có nghĩ nhóm tôi nên xây trợ lý AI không?”'],'a','Một sự kiện cụ thể mở ra workflow, workaround và hệ quả đã xảy ra.')
item(d,18,'Chuỗi bằng chứng nào hữu ích nhất để hiểu pain thực tế?', ['Sự kiện cụ thể → hành vi → workaround → hệ quả','Lời khen → ý định dùng → dự đoán mức phổ biến','Danh sách feature mong muốn → nhóm tự suy ra tần suất pain'],'a','Bằng chứng gắn hành vi và hệ quả với một trường hợp thực giúp giảm suy diễn từ ý kiến chung.')
item(d,19,'Khi hỏi “Nếu hệ thống gợi ý quyết định cho bạn thì sao?”, cuộc phỏng vấn chuyển trọng tâm sang đâu?', ['Phản ứng, tiêu chí chấp nhận và trust đối với một concept','Chỉ thu lịch sử hành vi hiện có mà chưa nhắc giải pháp','Tự xác nhận pain đã đủ lớn để triển khai'],'a','Concept interview khám phá phản ứng với giải pháp; problem interview tập trung chuyện, hành vi và pain hiện tại.')
item(d,20,'Vì sao lời hứa “sẽ dùng một công cụ tốt hơn” chưa phản ánh quyết định chuyển đổi thật?', ['Nó thường chưa xét giá, học lại và thay đổi workflow','Ý định tương lai luôn có độ tin cậy cao hơn hành vi quá khứ','Chỉ cần người trả lời lịch sự là có thể bỏ qua switching cost'],'a','Một giả định lý tưởng có thể loại các chi phí mà người dùng thực sự phải chịu khi chuyển.')
item(d,21,'Những cách hỏi nào phù hợp nguyên tắc Mom Test? (Chọn tất cả đáp án đúng.)',['Hỏi đời sống và công việc của người dùng thay vì quảng bá ý tưởng','Hỏi tình huống đã xảy ra cụ thể','Lắng nghe và hỏi tiếp diễn biến','Dành phần lớn thời gian giải thích vì sao giải pháp sẽ tốt'],['a','b','c'],'Nội dung quá khứ cụ thể và lắng nghe giảm việc tìm lời xác nhận cho ý tưởng của người phỏng vấn.')
item(d,22,'Muốn hiểu mức độ tốn kém của một pain, câu hỏi nào hữu ích hơn “bạn có mua tính năng X không”?', ['“Lần gần nhất việc này tốn bao nhiêu thời gian/chi phí, và bạn đã thử cách nào?”','“Bạn có thích X nếu nó không tốn tiền và không cần học lại không?”','“Bạn thấy X nên có bao nhiêu chức năng để trông đầy đủ?”'],'a','Chi phí và phương án đã thử cho thấy mức độ pain và nỗ lực giải quyết thực tế.')
item(d,23,'Người dùng nói “hãy thêm feature X”. Bước tìm hiểu tiếp hợp lý nhất là gì?', ['Hỏi hoàn cảnh, động cơ và công việc khiến họ cần X','Ghi X thành nhu cầu đã xác nhận và chuyển thẳng sang build','Bác bỏ X vì người dùng không nên đề xuất giải pháp'],'a','Yêu cầu feature là đầu mối để tìm job/pain, chưa tự giải thích nguyên nhân hay giá trị.')
item(d,24,'Tiêu chí tuyển người phỏng vấn nào tạo mẫu sát trải nghiệm cần nghiên cứu hơn?', ['Trong bảy ngày gần đây đã bị kẹt và tự tìm workaround cho việc đang nghiên cứu','Bất kỳ ai cùng nhãn nhân khẩu học dù chưa trải qua tình huống','Chỉ đồng nghiệp trong nhóm sản phẩm vì họ dễ tiếp cận'],'a','Trải nghiệm gần đây cụ thể giúp người tham gia kể sự kiện và hành động thay vì tưởng tượng chung.')
item(d,27,'Những thực hành nào giữ tính trung thực của dữ liệu phỏng vấn? (Chọn tất cả đáp án đúng.)',['Ghi facts trước khi diễn giải','Đón nhận bằng chứng làm yếu giả thuyết thay vì tranh luận bảo vệ','Có thể dùng AI rà câu hỏi dẫn dắt nhưng không tạo quote hay dữ liệu giả','Tạo thêm một vài câu trả lời hợp lý để đủ mẫu'],['a','b','c'],'Công cụ hỗ trợ cách hỏi không thay thế lời nói và hành vi thật; bằng chứng trái kỳ vọng vẫn có giá trị.')
d='p2-t1-d03'
item(d,5,'Có bằng chứng rằng người dùng gặp pain đã đủ chứng minh điều gì?', ['Vấn đề đáng tìm hiểu, chưa chứng minh một giải pháp cụ thể hiệu quả','Giải pháp đầu tiên của nhóm đã được xác nhận','Có thể bỏ quan sát hành vi khi thử prototype'],'a','Problem evidence và solution evidence trả lời hai câu hỏi khác nhau.')
item(d,6,'Sau khi gom pain thành pattern và learning question, giai đoạn Develop nên tạo ra gì?', ['Nhiều cơ chế giải pháp và micro-prototypes để học','Một bản hoàn chỉnh của lựa chọn đầu tiên trước khi thử','Kết luận go-to-market chỉ dựa trên tần suất pain'],'a','Develop mở không gian lựa chọn trước khi Deliver quan sát hành vi và tradeoff.')
item(d,7,'Trợ giúp user-led đặt gánh nặng nào lên người học?', ['Người học phải chủ động mở Help và biết mình cần dạng hỗ trợ nào','Người học phải sửa chẩn đoán AI trước mọi lần trợ giúp','Người học phải chấp nhận nudge AI tự mở mà không được yêu cầu'],'a','Quyền chủ động cao đi cùng chi phí tự nhận biết nhu cầu và tìm trợ giúp.')
item(d,7,'Một cơ chế collaborative hỗ trợ người học bằng cách nào?', ['AI hỏi về chỗ mắc rồi người học xác nhận hoặc sửa chẩn đoán','AI tự mở đáp án ngay khi phát hiện sai mà không hỏi','Hệ thống chờ người học tự chọn đúng loại tài liệu trong Help'],'a','Phối hợp giữ vai trò chẩn đoán của AI cùng quyền xác nhận/correct của người học, với chi phí thêm một bước hỏi.')
item(d,7,'Trợ giúp proactive cần cân nhắc tradeoff nào?', ['Hỗ trợ chủ động đúng lúc nhưng có thể gây gián đoạn hoặc cảm giác bị theo dõi','Luôn cần người học tự mở Help nên không thể gián đoạn','Không thể cho phép người học dismiss hoặc sửa chẩn đoán'],'a','AI chủ động có thể giảm effort tìm trợ giúp nhưng tăng rủi ro can thiệp không đúng lúc.')
item(d,8,'Vì sao yêu cầu “hỗ trợ đúng lúc” còn quá mơ hồ để thử nghiệm?', ['Chưa xác định khi nào kích hoạt, ai khởi xướng và tương tác cụ thể','Đã chỉ rõ toàn bộ cơ chế nên không cần prototype','Chỉ thiếu độ hoàn thiện hình ảnh, còn quyết định hành vi đã đủ'],'a','Prototype buộc nhóm chọn trigger và hành vi cụ thể mà người dùng có thể phản ứng.')
item(d,9,'Một test slice nên đạt độ hoàn thiện nào để học được từ người dùng?', ['Đủ thực để họ ra quyết định ở tương tác quan trọng','Bao phủ mọi màn hình và edge case trước khi được thử','Chỉ mô tả lời hứa để người dùng đoán mình sẽ làm gì'],'a','Mục đích là tạo quyết định có ý nghĩa, không phải hoàn thành toàn sản phẩm.')
item(d,11,'Những thành phần nào tạo một micro-prototype có quyết định thực? (Chọn tất cả đáp án đúng.)',['Ngữ cảnh cụ thể của người học','Tương tác AI quan trọng','Quyền accept/correct/dismiss hoặc quyết định tương ứng','Danh sách mọi tính năng tương lai thay cho tương tác'],['a','b','c'],'Context, critical interaction và user decision giúp người tham gia hành động thay vì chỉ nhận xét một lời hứa.')
item(d,12,'Cùng một giả thuyết về nhu cầu trợ giúp có thể được khám phá tốt hơn bằng cách nào?', ['Thử nhiều cơ chế giải quyết khác nhau','Coi cơ chế đầu tiên là hệ quả duy nhất của giả thuyết','Đổi sang pain khác mỗi khi prototype chưa được khen'],'a','Một nhu cầu có thể có nhiều cách can thiệp; so sánh giúp học cách phù hợp hơn.')
item(d,13,'Hai prototype được xem là khác cơ chế khi thay đổi loại quyết định nào?', ['Trigger, vai trò AI/user hoặc cách phục hồi khi hiểu sai','Chỉ màu nút và vị trí cùng một thông điệp','Chỉ tên gọi nhưng giữ nguyên mọi tương tác'],'a','Khác biệt nền tảng phải làm thay đổi cách đạt outcome hoặc phân chia quyền hành động.')
item(d,14,'So sánh nhiều lựa chọn thường cung cấp insight gì mà chỉ hỏi một lựa chọn dễ bỏ lỡ?', ['Tiêu chí lựa chọn và tradeoff khiến người dùng thích hướng này hơn hướng khác','Bảo đảm người dùng sẽ mua lựa chọn được thích nhất','Loại bỏ nhu cầu hỏi lý do đằng sau hành động'],'a','Phản ứng so sánh như thích được hỏi trước hay bị nudge quá sớm làm lộ tiêu chí thiết kế.')
item(d,15,'Parallel prototyping có lợi ích học tập nào so với chỉ sửa nối tiếp một hướng?', ['Mở nhiều hướng đồng thời và nhận phản hồi có tính so sánh','Tự chứng minh tất cả hướng đều giải quyết pain','Giữ nhóm tập trung duy nhất vào phiên bản ban đầu'],'a','Các phương án song song giảm việc chỉ tối ưu một hướng đã chọn và mở rộng phản hồi.')
item(d,16,'Ba prototype chỉ khác màu và vị trí chart nhưng giữ nguyên cách trợ giúp có hạn chế gì?', ['Chưa tạo các lựa chọn cơ chế thật để kiểm tra quyết định nền tảng','Đã kiểm tra được đầy đủ tradeoff về agency và trigger','Đã phân biệt được user-led với proactive chỉ qua trình bày'],'a','Nếu bỏ lớp hình ảnh vẫn mô tả cùng một cơ chế thì độ phân kỳ thiết kế còn thấp.')
item(d,17,'Một lựa chọn Wild có vai trò gì trong khám phá giải pháp?', ['Thách thức giả định nền tảng nhưng vẫn đủ đáng tin để người dùng phản ứng','Là lựa chọn cố tình kém để làm Standard nổi bật','Là lựa chọn đã được xác nhận tốt nhất trước khi thử'],'a','Wild mở một hướng khác như hỗ trợ từ người học khác, không phải nhãn xếp hạng chất lượng.')
item(d,18,'Vì sao nên đặt tên trung tính A/B/C khi cho người dùng so sánh prototype?', ['Tránh nhãn tên gợi trước phương án nào được nhóm ưu ái','Giúp người dùng nhận ra phiên bản nào nhóm muốn họ chọn','Cho phép bỏ phần quan sát hành vi vì tên đã trung lập'],'a','Nhãn trung tính giảm tín hiệu dẫn dắt đánh giá, còn bằng chứng vẫn cần quan sát.')
item(d,22,'Những yếu tố nào nên giữ cố định khi so sánh cơ chế trợ giúp cho cùng một learning question? (Chọn tất cả đáp án đúng.)',['Người dùng, tình huống và task','Nội dung và outcome mong muốn','Đổi đồng thời persona và dataset của mỗi lựa chọn','Trigger bắt buộc phải giống nhau dù đó là biến cần học'],['a','b'],'Giữ bối cảnh so sánh ổn định giúp quy khác biệt hành vi về cơ chế/agency đang được thay đổi.')
item(d,23,'Bằng chứng nào hỗ trợ quyết định thiết kế tiếp theo tốt hơn lời khen “hay đấy”?', ['Hành động đầu tiên, việc đọc/bỏ qua gợi ý và cách sửa khi AI hiểu sai','Số tính từ tích cực người dùng dùng để mô tả demo','Số lần nhóm giải thích vì sao phương án tốt trước khi user thao tác'],'a','Quan sát tương tác và recovery cho thấy cơ chế thực sự vận hành thế nào, giúp chọn vòng thiết kế kế tiếp.')
